parts.text:
{
  "title": "반려견 두부와 함께한 산책 경로 기록",
  "cards": [
    {
      "stamp_id": "stamp:e03",
      "title": "상가 밀집 지역으로의 이동",
      "text": "보호자와 반려견 두부가 등록 상가가 산재한 구간에서 등록 상가가 모인 구간으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e04",
      "title": "늘벗근린공원 인근으로 이동",
      "text": "등록 상가가 모인 구간에서 240초 후 늘벗근린공원 인근으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e05",
      "title": "양재천 인근으로 이동",
      "text": "늘벗근린공원 인근에서 240초 후 양재천 인근으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e06",
      "title": "상가 밀집 지역으로 복귀",
      "text": "양재천 인근에서 240초 후 등록 상가가 모인 구간으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e07",
      "title": "상가 적은 구간으로 이동",
      "text": "등록 상가가 모인 구간에서 180초 후 등록 상가가 적은 구간으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e08",
      "title": "양재천 인근에서의 거리 변화",
      "text": "양재천 인근에서 머무르며 양재천과의 거리가 가까워졌다가 다시 멀어지는 변화가 있었다."
    },
    {
      "stamp_id": "stamp:e09",
      "title": "상가 적은 구간으로 재진입",
      "text": "양재천 인근에서 180초 후 등록 상가가 적은 구간으로 이동하였다."
    }
  ]
}
